INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65072653', 65072653, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL BINA ADMINISTRASI KEWILAYAHAN', 'Asisten Tenaga Ahli', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 57210000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', 'Sehubungan dengan itu, pengadaan Jasa Konsultan Asisten Tenaga Ahli Untuk Dukungan Penguatan Terhadap Tata Kelola Koperasi Merah Putih Kelurahan/Desa menjadi elemen strategis untuk mendukung Direktorat Dekonsentrasi Tugas Pembantuan dan Kerja Sama dalam melaksanakan pendampingan teknis dan evaluasi tata kelola koperasi. Asisten Tenaga ahli ini diharapkan dapat memberikan dukungan kepada tenaga ahli dalam melakukan evaluasi dan analisis untuk menguatkan kapasitas kelembagaan, memberikan rekomendasi perbaikan tata kelola, serta menyusun mekanisme monitoring dan evaluasi yang berkelanjutan untuk memastikan koperasi Merah Putih dapat memenuhi tujuan sosial-ekonominya, kebijakan dan program yang dijalankan menjadi lebih efektif, efisien, dan berkelanjutan dalam rangka meningkatkan kesejahteraan masyarakat serta memperkokoh perekonomian nasional berbasis koperasi.', 'Maksud dan Tujuan kegiatan Asisten Tenaga Ahli Untuk Dukungan Penguatan Terhadap Tata Kelola Koperasi Merah Putih Kelurahan/Desa pada Direktorat Dekonsentrasi Tugas Pembantuan dan Kerja Sama adalah sebagai berikut: 1. Maksud Kegiatan 1) Memberikan dukungan kepada Tenaga Ahli untuk menyusun konsep kajian pendampingan teknis dan evaluasi tata kelola koperasi Merah Putih di tingkat desa/ kelurahan, agar koperasi dapat beroperasi secara efektif, transparan, dan akuntabel. 2) Menyediakan data dan rekomendasi berbasis evaluasi yang dapat digunakan Tenaga Ahli Koperasi Desa/Kelurahan Merah Putih pada Direktorat Dekonsentrasi Tugas Pembantuan dan Kerja Sama untuk perumusan kebijakan, monitoring, dan pembinaan koperasi secara berkelanjutan. 2. Tujuan Kegiatan 1) Memberikan dukungan kepada Tenaga Ahli dalam melakukan evaluasi dan analisis terhadap peningkatan kapasitas pengurus koperasi dalam hal manajemen, administrasi, dan pengelolaan keuangan sesuai prinsip Good Cooperative Governance. 2) Memberikan dukungan kepada Tenaga Ahli dalam melakukan evaluasi dan analisis terhadap penerapan tata kelola koperasi yang efektif, transparan, dan akuntabel, sehingga koperasi Merah Putih dapat beroperasi secara berkelanjutan dan memberikan manfaat maksimal bagi anggota. 3) Menyediakan data dan hasil evaluasi yang akurat sebagai dasar pengambilan keputusan, monitoring, dan pembinaan koperasi oleh Tenaga Ahli Koperasi Desa/Kelurahan Merah Putih pada Direktorat Dekonsentrasi Tugas Pembantuan dan Kerja Sama. 4) Memberikan dukungan kepada Tenaga Ahli dalam melakukan evaluasi dan analisis dalam memberikan rekomendasi perbaikan tata kelola dan praktik terbaik yang dapat diadopsi oleh koperasi desa/kelurahan untuk meningkatkan kinerja dan daya saing.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1944192);
