INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65076403', 65076403, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Tenaga Ahli Hukum 3', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 51150000, 'March 2026', 'APBD', 1, 1, '1 orang x 3 bulan', 'a) Melakukan pendampingan dan pembelaan hukum terhadap Instansi dan/atau ASN terkait dengan permasalahan hukum administrasi kependudukan berdasarkan panggilan dari Pengadilan di lingkungan Dinas Kependudukan dan Pencatatan Sipil Provinsi Jakarta maupun Suku Dinas Kependudukan dan Pencatatan Sipil Kab/Kota Administrasi; b) Memenuhi panggilan dari Pengadilan secara langsung dari Pengadilan terkait dengan permasalahan hukum administrasi kependudukan maupun permalasahan hukum lainnya; c) Menyusun dokumen hukum yang diperlukan sesuai dengan ketentuan perundang-undangan yang berlaku guna kepentingan pemenuhan panggilan persidangan; d) Memberikan pertimbangan, analisa dan opini hukum baik secara lisan maupun tertulis terkait penyelesaian permasalahan administrasi kependudukan maupun bidang hukum lainnya dalam rangka pendampingan, pembelaan hukum ASN dan pemenuhan panggilan Persidangan; e) Melakukan identifikasi permasalahan hukum administrasi kependudukan di lingkungan Dinas Kependudukan dan Pencatatan Sipil Provinsi DKI Jakarta maupun Suku Dinas Kependudukan dan Pencatatan Sipil Kabupaten/Kota Administrasi; f) Melakukan monitoring secara keseluruhan terhadap pemenuhan panggilan Persidangan yang sedang berjalan dan melaporkan perkembangannya kepada pimpinan; g) Membuat laporan bulanan dan triwulan hasil kinerja serta rekapitulasi seluruh hasil pekerjaan sebagaimana di atas; h) Menyerahkan seluruh dokumentasi hasil pekerjaan kepada PPK melalui PPTK; dan i) Menjalankan tugas dan pekerjaan lainnya sesuai dengan arahan pimpinan.', 'a) Warga Negara Indonesia b) Diutamakan memiliki Kartu Tanda Penduduk (KTP) wilayah Jabodetabek; c) Berusia 30 – 50 Tahun; d) Memiliki Nomor Pokok Wajib Pajak (NPWP); e) Pendidikan minimal Magister Hukum/ S-2 Hukum yang diutamakan sebagai berikut: IPK minimal 3.00 dalam skala 4.00 untuk Perguruan Tinggi Negeri yang Terakreditasi minimal B dari BAN-PT; dan IPK minimal 3.25 dalam skala 4.00 untuk Perguruan Tinggi Swasta yang Terakreditasi minimal A dari BAN-PT; f) Memiliki sertifikasi profesi Advokat dibuktikan dengan Berita Acara Sumpah dan Kartu Tanda Advokat yang masih aktif dan terdaftar dalam organisasi profesi Advokat; g) Memiliki pengalaman kerja di bidang hukum minimal 3 tahun dibuktikan dengan Surat Pengalaman Kerja yang diterbitkan oleh Badan/Lembaga/Instansi Pemberi Kerja dan portofolio pekerjaan yang relevan (Pengalaman bekerja di Kantor atau Firma Hukum diutamakan); h) Memiliki pengetahuan dan wawasan terkait administrasi kependudukan; i) Memiliki kemampuan berkomunikasi dan kemampuan interpersonal yang baik serta pemecahan masalah yang cepat; j) Memiliki integritas, disiplin bekerja dan mampu bekerja dalam tekanan baik individu maupun dalam tim serta dapat menyelesaikan pekerjaan sesuai target; k) Mengoperasikan Microsoft Office (Word, Excel dan PowerPoint); l) Siap bekerja di luar jam kerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1949102);
